import { render, screen } from '@testing-library/react'
import { describe, it, expect, vi } from 'vitest'
import { useCurrentUser } from './useCurrentUser'
import Dashboard from './Dashboard'

vi.mock('./useCurrentUser', () => ({
  useCurrentUser: vi.fn(),
}))

describe('Dashboard', () => {
  it('greets the logged-in user', () => {
    vi.mocked(useCurrentUser).mockReturnValue({
      name: 'Grace Hopper',
      role: 'admin',
    })

    render(<Dashboard />)
    expect(screen.getByText('Welcome, Grace Hopper')).toBeDefined()
  })
})

import { render, screen, fireEvent, waitFor } from '@testing-library/react'
import { describe, it, expect, vi } from 'vitest'
import ResultsPage from './ResultsPage'

vi.mock('./api')

const { searchPosts } = await import('./api')

describe('ResultsPage', () => {
  it('calls the search API with the typed term', async () => {
    render(<ResultsPage />)

    fireEvent.change(screen.getByRole('searchbox'), {
      target: { value: 'react testing' },
    })

    await waitFor(() =>
      expect(searchPosts).toHaveBeenCalledTimes(1)
    )
    expect(searchPosts).toHaveBeenCalledWith('react testing')
  })
})

